#define LORA_NSS 10
#define LORA_RST 9
#define LORA_DIO0 2

void setup() {
 Serial.begin(115200);
 LoRa.setPins(LORA_NSS, LORA_RST, LORA_DIO0);
 if (!LoRa.begin(433E6)) { // match your region's LoRa frequency (433/868/915 MHz)
 Serial.println("LoRa init failed!");
 while (1) delay(10);
 }
}

